// Writes the generated teaching documents of ../../docs/teaching/<lang>/ from the sources of the course:
//   exit-tickets.md   for the students: the outcomes of each lecture and its exit ticket (no answers)
//   rubrics.md        for the instructor: every assessment item with its concepts, rubric and likely misconception
//   roadmaps.md       for both: per lecture, the outcomes, the learning status, what it builds on, the bridges, the closing
// Sources: concepts/assessments.json, concepts/bridges.json, concepts/registry.json, decks/mastery.js.  Do not edit
// the outputs by hand.   node textbook/teaching_docs.js   (from tools/)
const fs = require("fs"), path = require("path");
const { spawnSync } = require("child_process");
if (process.argv[2] !== "--lang") {   // the specifications are loaded once per process: one child per language
  let bad = 0;
  for (const l of ["en", "it"]) bad += spawnSync(process.execPath, [__filename, "--lang", l], { stdio: "inherit" }).status ? 1 : 0;
  process.exit(bad ? 1 : 0);
}
const lang = process.argv[3];
const { loadDecks } = require("../lib/lang");
const M = require("../lib/mastery");
const RM = require("../lib/roadmap");
const A = require("../concepts/assessments.json");
const specs = Object.fromEntries(loadDecks(lang, { raw: true }).map((d) => [d.n, d]));
const titles = Object.fromEntries(Object.values(specs).map((d) => [d.n, d.title]));
const OUT = path.resolve(__dirname, "..", "..", "docs", "teaching", lang);
fs.mkdirSync(OUT, { recursive: true });

const W = {
  en: { lecture: "Lecture", gen: "Generated by `tools/textbook/teaching_docs.js` from `tools/concepts/assessments.json`, `bridges.json` and the registry: do not edit by hand.",
    tickets: "Exit tickets", ticketsIntro: "One ticket per lecture: one or two questions, two to four minutes, alone and on paper, at the end of the lecture. They are not marked: they tell you, and the instructor, what is clear and what is not yet. The answers are discussed at the start of the next lecture.",
    outcomes: "Outcomes", rubrics: "Assessment items and rubrics (instructor)", rubricsIntro: "Every item of the course with the concepts it checks (ids of `tools/concepts/registry.json`), where it is used, the expected reasoning and a misconception to listen for. *exit*: the exit ticket; *checkpoint*: asked during the lecture, on the slide named; *check*: extra practice. Not for projection: the rubrics contain the answers.",
    kind: "Kind", concepts: "Concepts", where: "Where", prompt: "Prompt", rubric: "Rubric", misconception: "Misconception to listen for", level: "level: use (the concept is used, not studied)",
    slide: "slide of the specification", handout: "exit ticket, handout or last slide notes",
    roadmaps: "Lecture roadmaps", roadmapsIntro: "For each lecture: what it builds on, today's outcomes, the learning status of its concepts, the bridges that recall what was deferred, the next step and the closing thread. The same text opens the notes of each deck and the chapter of the textbook.",
    status: "Learning status" },
  it: { lecture: "Lezione", gen: "Generato da `tools/textbook/teaching_docs.js` a partire da `tools/concepts/assessments.json`, `bridges.json` e dal registro: non modificare a mano.",
    tickets: "Biglietti d'uscita", ticketsIntro: "Un biglietto per lezione: una o due domande, da due a quattro minuti, da soli e su carta, alla fine della lezione. Non sono valutati: dicono a voi, e al docente, che cosa è chiaro e che cosa non ancora. Le risposte si discutono all'inizio della lezione successiva.",
    outcomes: "Risultati", rubrics: "Prove formative e griglie di valutazione (docente)", rubricsIntro: "Ogni prova del corso con i concetti che verifica (id di `tools/concepts/registry.json`), dove si usa, il ragionamento atteso e un errore tipico da riconoscere. *exit*: il biglietto d'uscita; *checkpoint*: posta durante la lezione, sulla slide indicata; *check*: esercizio in più. Da non proiettare: le griglie contengono le risposte.",
    kind: "Tipo", concepts: "Concetti", where: "Dove", prompt: "Domanda", rubric: "Griglia", misconception: "Errore tipico da riconoscere", level: "livello: uso (il concetto si usa, non si studia)",
    slide: "slide della specifica", handout: "biglietto d'uscita, foglio o note dell'ultima slide",
    roadmaps: "Percorsi delle lezioni", roadmapsIntro: "Per ogni lezione: su che cosa si appoggia, i risultati di oggi, lo stato di apprendimento dei suoi concetti, i ponti che richiamano ciò che era stato rinviato, il prossimo passo e il filo della lezione. Lo stesso testo apre le note di ogni presentazione e il capitolo del libro.",
    status: "Stato di apprendimento" },
}[lang];
const lectures = Object.keys(specs).sort();
const head = (t, intro) => [`# ${t}`, "", `*${W.gen}*`, "", intro, ""];

// exit tickets (students)
let o = head(W.tickets, W.ticketsIntro);
for (const n of lectures) {
  o.push(`## ${W.lecture} ${n}: ${titles[n]}`, "", `**${W.outcomes}.** ${RM.lec(n).outcomes[lang].map((x, i) => (i && /^[A-Z][a-z]/.test(x) ? x[0].toLowerCase() + x.slice(1) : x)).join("; ")}.`, "");
  RM.exitItems(n).forEach((it, i) => o.push(`${i + 1}. ${it.prompt[lang]}`));
  o.push("");
}
fs.writeFileSync(path.join(OUT, "exit-tickets.md"), o.join("\n"));

// rubrics (instructor)
o = head(W.rubrics, W.rubricsIntro);
for (const n of lectures) {
  o.push(`## ${W.lecture} ${n}: ${titles[n]}`, "");
  for (const [id, it] of Object.entries(A.items).filter(([, x]) => x.lecture === n)) {
    const where = it.source ? `${W.slide} ${it.source}` : W.handout;
    o.push(`### ${id} (${it.kind})`, "", `- **${W.concepts}:** ${it.concepts.map((c) => `\`${c}\` (${M.CONCEPTS[c].label[lang]})`).join(", ")}${it.level === "use" ? `; ${W.level}` : ""}`,
      `- **${W.where}:** ${where}`, `- **${W.prompt}:** ${it.prompt[lang]}`, `- **${W.rubric}:** ${it.rubric[lang]}`, `- **${W.misconception}:** ${it.misconception[lang]}`, "");
  }
}
fs.writeFileSync(path.join(OUT, "rubrics.md"), o.join("\n"));

// roadmaps (both)
o = head(W.roadmaps, W.roadmapsIntro);
for (const n of lectures) {
  o.push(`## ${W.lecture} ${n}: ${titles[n]}`, "", RM.notesText(lang, specs[n], titles).split("\n\n").join("\n\n"), "", `**${W.status}.** ${M.summaryText(lang, specs[n])}`, "");
}
fs.writeFileSync(path.join(OUT, "roadmaps.md"), o.join("\n"));
console.log(`docs/teaching/${lang}: exit-tickets.md, rubrics.md, roadmaps.md (${lectures.length} lectures, ${Object.keys(A.items).length} items)`);
